          "text_kr": "ETCDCTL_API=3 etcdctl snapshot save /var/lib/etcd-backup-30.db --endpoints=https://192.168.1.100:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key"
